import java.nio.file.*;import jdk.internal.org.objectweb.asm.*;import jdk.internal.org.objectweb.asm.tree.*;
public class Patch{public static void main(String[] args)throws Exception{Path root=Path.of(args[0]);int count=0;try(var files=Files.walk(root)){for(Path p:files.filter(f->f.toString().endsWith("Screen.class")).toList()){ClassNode c=new ClassNode();new ClassReader(Files.readAllBytes(p)).accept(c,0);if(!c.superName.equals("net/minecraft/client/gui/screens/Screen"))continue;MethodNode init=c.methods.stream().filter(m->m.name.equals("init")&&m.desc.equals("()V")).findFirst().orElse(null);if(init==null){init=new MethodNode(Opcodes.ACC_PROTECTED,"init","()V",null,null);init.instructions.add(new VarInsnNode(Opcodes.ALOAD,0));init.instructions.add(new MethodInsnNode(Opcodes.INVOKESPECIAL,c.superName,"init","()V",false));init.instructions.add(new InsnNode(Opcodes.RETURN));c.methods.add(init);}InsnList hook=new InsnList();hook.add(new VarInsnNode(Opcodes.ALOAD,0));hook.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/survivorcreator/hudscale/ScreenScale","enter","(Ljava/lang/Object;)V",false));init.instructions.insert(hook);
MethodNode removed=c.methods.stream().filter(m->m.name.equals("removed")&&m.desc.equals("()V")).findFirst().orElse(null);if(removed==null){removed=new MethodNode(Opcodes.ACC_PUBLIC,"removed","()V",null,null);removed.instructions.add(new VarInsnNode(Opcodes.ALOAD,0));removed.instructions.add(new MethodInsnNode(Opcodes.INVOKESPECIAL,c.superName,"removed","()V",false));removed.instructions.add(new InsnNode(Opcodes.RETURN));c.methods.add(removed);}for(AbstractInsnNode n:removed.instructions.toArray())if(n.getOpcode()==Opcodes.RETURN){InsnList restore=new InsnList();restore.add(new VarInsnNode(Opcodes.ALOAD,0));restore.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/survivorcreator/hudscale/ScreenScale","exit","(Ljava/lang/Object;)V",false));removed.instructions.insertBefore(n,restore);}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);Files.write(p,w.toByteArray());System.out.println(c.name+" fixed screen scale and restore");count++;}}if(count!=4)throw new AssertionError("Expected four screens: "+count);}}
